    if patient.duration_of_condition > 365: 
        score += 3
    elif patient.duration_of_condition > 180: 
        score += 2
    elif patient.duration_of_condition > 60: 
        score += 1

    # Higher number of comorbidities increases priority
    score += (patient.comorbidities // 2) * 2

    # Adjust score based on resources
    if patient.resource_availability <= 0:
        score -= 3  # If not available, decrease priority
    elif patient.resource_availability <= 5:
        score -= 2  # If limited, decrease priority
    elif patient.resource_availability <= 10:
        score -= 1  # If moderate, decrease priority slightly

    return max(0, score)  # Ensure score never goes below zero

