    """
    Compute the beta-blocker therapy priority of the patient.
    patient: A patient object with attributes: severity, duration_of_condition, insurance status (insured, underinsured, uninsured), resource_availability, age, comorbidities, symptoms
    """
    score = 0

    # Increase priority based on severity (higher severity = higher priority)
    if patient.severity >= 7:
        score += 4
    elif 4 <= patient.severity < 7:
        score += 3
    elif 2 <= patient.severity < 4:
        score += 2
    else:
        score += 1

    # Increase priority based on symptom duration
    if patient.duration_of_condition > 12:  # more than 3 months
        score += 3
    elif 4 < patient.duration_of_condition <= 12:  # 1 to 3 months
        score += 2

    # Increase priority if patient is insured
    if patient.insurance_status == 'insured':
        score += 4
    elif patient.insurance_status == 'underinsured':
        score += 3

    # Higher number of comorbidities increases priority
    if patient.comorbidities >= 3:
        score += 3
    elif patient.comorbidities >= 1:
        score += 2

    # Reduce priority for younger patients, as they might not respond well to beta-blockers
    if patient.age < 65:
        score -= 1

    # If resources are abundant and the patient is uninsured, decrease the score
    if patient.resource_availability == 'abundant' and patient.insurance_status == 'uninsured':
        score -= 2

    # Score should be at least 1 to be considered, but not more than 10 (the maximum we originally assigned for severe symptoms)
    return max(1, min(score, 10))

