def derivative(func, x, dx=1e-6):
    """Estimate the derivative of a function using the finite difference method."""
    return (func(x + dx / 2) - func(x - dx / 2)) / dx

def newton_raphson(func, x0, tol=1e-5, max_iter=1000):
    """Find a root of a function using the Newton-Raphson method."""
    xn = x0
    for n in range(max_iter):
        fxn = func(xn)
        if abs(fxn) < tol:
            return xn
        dfxn = derivative(func, xn)
        if dfxn == 0:
            raise Exception('The derivative of the function is zero.')
        xn = xn - fxn / dfxn
    raise Exception('The method did not converge.')

